import{_ as i,c as t,o,aj as a}from"./chunks/framework.Id7s26SP.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli/config.md","filePath":"reference/cli/config.md"}'),s={name:"reference/cli/config.md"};function l(n,e,r,c,d,p){return o(),t("div",null,[...e[0]||(e[0]=[a('<h2 id="primitive-config" tabindex="-1"><code>primitive config</code> <a class="header-anchor" href="#primitive-config" aria-label="Permalink to “primitive config”">​</a></h2><p>Manage app configuration as TOML files — author locally, then pull/diff/push against the server</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive config [options]</span></span></code></pre></div><h3 id="primitive-config-fields" tabindex="-1"><code>primitive config fields</code> <a class="header-anchor" href="#primitive-config-fields" aria-label="Permalink to “primitive config fields”">​</a></h3><p>List a configuration type&#39;s TOML keys, types, required and default</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive config fields &lt;type&gt; [options]</span></span></code></pre></div><p>Arguments:</p><ul><li><code>&lt;type&gt;</code> — Configuration type (13 available)</li></ul><p>Options:</p><ul><li><code>--json</code> — Output as JSON</li></ul><h3 id="primitive-config-create" tabindex="-1"><code>primitive config create</code> <a class="header-anchor" href="#primitive-config-create" aria-label="Permalink to “primitive config create”">​</a></h3><p>Scaffold a configuration file locally (no API call)</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive config create &lt;type&gt; [key] [options]</span></span></code></pre></div><p>Arguments:</p><ul><li><code>&lt;type&gt;</code> — Configuration type — see &#39;primitive config fields&#39;</li><li><code>[key]</code> — The object&#39;s key; it becomes the file name (none for user-properties, a single file)</li></ul><h3 id="primitive-config-set" tabindex="-1"><code>primitive config set</code> <a class="header-anchor" href="#primitive-config-set" aria-label="Permalink to “primitive config set”">​</a></h3><p>Set a field in a configuration file locally (no API call)</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive config set &lt;object&gt; &lt;assignments...&gt; [options]</span></span></code></pre></div><p>Arguments:</p><ul><li><code>&lt;object&gt;</code> — &lt;type&gt;/&lt;key&gt;, app, user-properties, or vars</li><li><code>&lt;assignments...&gt;</code> — One or more &lt;path&gt;=&lt;value&gt;, e.g. prompt.description=&quot;Summarize&quot;</li></ul><h3 id="primitive-config-init" tabindex="-1"><code>primitive config init</code> <a class="header-anchor" href="#primitive-config-init" aria-label="Permalink to “primitive config init”">​</a></h3><p>Initialize the config directory structure</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive config init [options]</span></span></code></pre></div><h3 id="primitive-config-pull" tabindex="-1"><code>primitive config pull</code> <a class="header-anchor" href="#primitive-config-pull" aria-label="Permalink to “primitive config pull”">​</a></h3><p>Download configuration from server to TOML files</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive config pull [options]</span></span></code></pre></div><p>Options:</p><ul><li><code>--json</code> — Output as JSON instead of writing files</li><li><code>--only &lt;selectors&gt;</code> — Fetch just these objects: &lt;type&gt;/&lt;key&gt;, app, or var/&lt;key&gt; (repeatable, or comma-separated). Everything else in the slot is left as it is. (default: <code>[]</code>)</li><li><code>--no-prune</code> — Keep local files for entities that are absent from the sync export (the next push will re-create them)</li></ul><p>Variants:</p><ul><li><code>database-type-configs</code>: <strong><code>Deprecated</code></strong></li><li><code>db3</code>: <strong><code>Beta</code></strong></li><li><code>metadata-categories</code>: <strong><code>Beta</code></strong> <strong><code>Deprecated</code></strong></li><li><code>user-properties</code>: <strong><code>Beta</code></strong></li></ul><h3 id="primitive-config-push" tabindex="-1"><code>primitive config push</code> <a class="header-anchor" href="#primitive-config-push" aria-label="Permalink to “primitive config push”">​</a></h3><p>Upload local TOML configuration to server</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive config push [options]</span></span></code></pre></div><p>Options:</p><ul><li><code>--dry-run</code> — Show what would be changed without applying</li><li><code>--force</code> — Overwrite remote even if modified since last pull</li><li><code>--only &lt;selectors&gt;</code> — Apply just these objects: &lt;type&gt;/&lt;key&gt;, app, or var/&lt;key&gt; (repeatable, or comma-separated). Everything else about push is unchanged. (default: <code>[]</code>)</li><li><code>--prune</code> — Delete remote entities whose local TOML was removed since the last sync</li><li><code>-y, --yes</code> — Skip the interactive confirmation before pruning or before lowering or removing a client version minimum in app.toml (for CI / automation)</li><li><code>--accept-warnings</code> — Commit schema diffs that have operations with dynamic refs, via the SCHEMA_HAS_UNCHECKABLE_OPS escape hatch</li><li><code>--allow-field-removal</code> — Push db3 type changes that would make stored records unreadable (removed fields or models, changed types). Needs <code>[app] allowFieldRemoval = true</code> already stored by an earlier push</li><li><code>--no-typecheck</code> — Ship function code without typechecking it against the declarations this push generates</li></ul><p>Variants:</p><ul><li><code>database-type-configs</code>: <strong><code>Deprecated</code></strong></li><li><code>db3</code>: <strong><code>Beta</code></strong></li><li><code>metadata-categories</code>: <strong><code>Beta</code></strong> <strong><code>Deprecated</code></strong></li><li><code>user-properties</code>: <strong><code>Beta</code></strong></li></ul><h3 id="primitive-config-diff" tabindex="-1"><code>primitive config diff</code> <a class="header-anchor" href="#primitive-config-diff" aria-label="Permalink to “primitive config diff”">​</a></h3><p>Show differences between local and remote configuration</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive config diff [options]</span></span></code></pre></div><p>Options:</p><ul><li><code>--only &lt;selectors&gt;</code> — Compare just these objects: &lt;type&gt;/&lt;key&gt;, app, or var/&lt;key&gt; (repeatable, or comma-separated). (default: <code>[]</code>)</li><li><code>--json</code> — Output as JSON: the app.toml field diff with --only app, the compared rows otherwise</li></ul><p>Variants:</p><ul><li><code>database-type-configs</code>: <strong><code>Deprecated</code></strong></li><li><code>db3</code>: <strong><code>Beta</code></strong></li><li><code>metadata-categories</code>: <strong><code>Beta</code></strong> <strong><code>Deprecated</code></strong></li><li><code>user-properties</code>: <strong><code>Beta</code></strong></li></ul><h3 id="primitive-config-revert" tabindex="-1"><code>primitive config revert</code> <a class="header-anchor" href="#primitive-config-revert" aria-label="Permalink to “primitive config revert”">​</a></h3><p>Restore the config directory from a snapshot taken before a previous pull</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive config revert [options]</span></span></code></pre></div><p>Options:</p><ul><li><code>--snapshot &lt;id&gt;</code> — Snapshot id (timestamp dirname or a unique &gt;=8-char prefix)</li><li><code>--list</code> — List available snapshots without restoring</li><li><code>-y, --yes</code> — Skip the confirmation prompt</li></ul>',49)])])}const f=i(s,[["render",l]]);export{h as __pageData,f as default};
